// Use "take" to view a sample number of records in the table and check the data.
YOUR_TABLE_HERE
| take 100
Monitoring Eventhouse
// See how many records are in the table.
YOUR_TABLE_HERE
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)

EventhouseCommandLogs
| take 100


EventhouseCommandLogs    // count the number of rows from the result   
| count 


EventhouseCommandLogs
| take 100


FunctionSetMetrics
|take 100 


let nested_bonds = 
(
    let bounds = 
    EventhouseCommandLogs
    | summarize 
        maxx = max(Timestamp), 
        minn = min(Timestamp), 
        min_cap = min(CapacityId);

    bounds
    | join kind=inner (
        EventhouseCommandLogs
    ) on $left.min_cap == $right.CapacityId;
);
nested_bonds
|take 100
